    "reasoning_traceability": {
      "status": "review",
      "note": "The investigative pathway is traceable (informal EEO complaint → formal investigation → OPR case → FAD decision), but the FAD's reasoning for concluding Complainant 'failed to prove discrimination' is absent; the record does not show how the Agency weighed Complainant's allegation against the OPR denial or addressed temporal proximity between harassment and adverse employment actions."
    },
    "cold_reviewer_clarity": {
      "status": "review",
      "note": "A reviewer years later could reconstruct the factual events and timeline, but cannot independently assess the investigative conclusions because the OPR Bluebook Report itself is not reproduced, only summarized as finding allegations 'unfounded' without showing the investigator's reasoning or how specific denials rebut Complainant's detailed account."
    },
    "accountability_support": {
      "status": "gap",
      "note": "The record documents Complainant's allegations and identifies potential corroborating documents (travel vouchers, field reports, email monitoring audit), but does not show whether the Agency actually retrieved, reviewed, or explained why these documents were unavailable or unhelpful to support or refute the discrimination claim."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "The chronology is clearly marked: detail July 2016, detail ended October 2016, transfer September 2017, 'off the books' investigation June 2017–June 2018, nonselections April and May 2018, EEO complaint June 2018, OPR notification August 2018, OPR report October 2018, assignment September 2018."
    }
  },
  "remediation_note": "A compliant record must include the FAD's explicit reasoning for rejecting the discrimination claim, particularly how it addressed the temporal nexus between the alleged harassment and adverse employment actions, and must incorporate or summarize the OPR investigation's specific findings and the evidentiary basis for its conclusions rather than merely asserting denials were made.",
  "finding": {
    "ai_function": "narrative",
    "condition_triggered": "reasoning_traceability, cold_reviewer_clarity, accountability_support",
    "compliant_version": "The FAD decision must state: (1) the standard applied (causal link between protected conduct and adverse action); (2) which evidence supports and which contradicts the discrimination allegation; (3) why identified documents were not obtained or how their absence affects the analysis; (4) how the OPR findings interact with the EEO investigation; and (5) the decision-maker's assessment of Complainant's credibility and the supervisors' denials in light of the detailed, contemporaneous nature of the allegations."
  }
}
